css:
/* From Uiverse.io by Li-Deheng - Tags: button, input, copy, color, line, hover effect, input effect , hover button */
.__UIV_SCOPE__ .info-panels {
  --color-icon: #fff;
  --color-input: #ccc;
  --color-border: #9e9e9e;
  --color-border-hover: #1a73e8;
  --all-transition: all .2s ease-out;
  --input-focus-opacity: .3;
}

.__UIV_SCOPE__ .input-color-group-one {
  position: relative;
}

.__UIV_SCOPE__ .input-color {
  max-width: 230px;
  min-width: 150px;
  border: 1.5px solid var(--color-border);
  border-radius: 80px;
  background: none;
  padding: 16px;
  font-size: 16px;
  transition: var(--all-transition);
}

.__UIV_SCOPE__ .input-color:focus {
  color: var(--color-input);
  outline: none;
  border: 1.5px solid var(--color-border-hover);
}

.__UIV_SCOPE__ .input-color:valid {
  color: var(--color-input);
  outline: none;
}

.__UIV_SCOPE__ .input-color::-webkit-input-placeholder {
  color: var(--color-input);
}

.__UIV_SCOPE__ .input-color::-moz-input-placeholder {
  color: var(--color-input);
}

.__UIV_SCOPE__ .input-color::-ms-input-placeholder {
  color: var(--color-input);
}

.__UIV_SCOPE__ .input-color:focus::-webkit-input-placeholder, .__UIV_SCOPE__ input-color:valid::-webkit-input-placeholder {
  opacity: var(--input-focus-opacity);
}

.__UIV_SCOPE__ .input-color:focus::-moz-input-placeholder, .__UIV_SCOPE__ input-color:valid::-moz-input-placeholder {
  opacity: var(--input-focus-opacity);
}

.__UIV_SCOPE__ .input-color:focus::-ms-input-placeholder, .__UIV_SCOPE__ input-color:valid::-ms-input-placeholder {
  opacity: var(--input-focus-opacity);
}

.__UIV_SCOPE__ .color-label {
  position: absolute;
  display: flex;
  justify-content: center;
  align-items: center;
  color: var(--color-border);
  font-weight: 600;
  padding: 0 5px;
  border: 1.5px solid var(--color-border);
  border-radius: 20px;
  top: -11.5px;
  left: 25px;
  background-color: transparent;
  cursor: default;
  backdrop-filter: blur(10px);
  transition: var(--all-transition);
}

.__UIV_SCOPE__ .input-color:focus ~ .color-label, .__UIV_SCOPE__ input-color:valid ~ .color-label {
  color: var(--color-border-hover);
  border: 1.5px solid var(--color-border-hover);
}

.__UIV_SCOPE__ .btn-copy {
  position: absolute;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 24px;
  height: 24px;
  border: 1.5px solid var(--color-border);
  border-radius: 50%;
  top: -11.5px;
  right: 25px;
  background-color: transparent;
  cursor: pointer;
  backdrop-filter: blur(10px);
  transition: var(--all-transition);
}

.__UIV_SCOPE__ .btn-copy:hover {
  background-color: var(--color-border);
  transform: scale(1.2);
}

.__UIV_SCOPE__ .btn-copy:active {
  transform: scale(1.1);
}

.__UIV_SCOPE__ .input-color:focus ~ .btn-copy {
  border: 1.5px solid var(--color-border-hover);
}

.__UIV_SCOPE__ .input-color:valid .input-color:focus ~ .btn-copy {
  border: 1.5px solid var(--color-border);
}

.__UIV_SCOPE__ .input-color:focus ~ .btn-copy:hover {
  background-color: var(--color-border-hover);
}

.__UIV_SCOPE__ #icon-btn-copy {
  fill: var(--color-border);
}

.__UIV_SCOPE__ .btn-copy:hover #icon-btn-copy {
  fill: var(--color-icon);
}

.__UIV_SCOPE__ .input-color:focus ~ .btn-copy #icon-btn-copy {
  fill: var(--color-border-hover);
}

.__UIV_SCOPE__ .input-color:focus ~ .btn-copy:hover #icon-btn-copy, .__UIV_SCOPE__ .input-color:valid ~ .btn-copy:hover #icon-btn-copy {
  fill: var(--color-icon);
}
